// Event Row: the sub entry carries one item with the same keys as a launch row (Client, Table,
// View, and for the insert doors Domains). This is how an insert door calls this machine after
// landing: Table "Companies", View "Not Sourced", Domains = what it just landed. Shape it like
// Fetch Launch Record's output so Resolve Base and Launch Params read one shape on both entries;
// the camelCase spellings a door might send are folded into the row keys here. Anything else a
// caller still sends from the old contract (Tiers, Sources, Departments, Roles, Max companies) is
// carried but never read (ruled 2026-09-08: the launch row is Client, Table, View, Tag).
const j=$input.first().json||{};
const f=(j.fields&&typeof j.fields==='object')?Object.assign({},j.fields):Object.assign({},j);
const arr=(v)=>Array.isArray(v)?v:(v?[v]:[]);
const alias=(key,alts)=>{ if(f[key]===undefined||f[key]===''||f[key]===null){ for(const a of alts){ if(f[a]!==undefined&&f[a]!==''&&f[a]!==null){ f[key]=f[a]; break; } } } };
alias('Table',['table']); alias('View',['view']); alias('Tag',['tag']);
// Domains: optional, event callers only. The insert doors pass the domains they just landed so the
// pull is scoped to them inside the view (added 2026-09-06 after three 5,000-company sweeps of a
// migrated backlog). A launch row has no such field and reads the whole view, as before.
alias('Domains',['domains']); f.Domains=arr(f.Domains).map(x=>String(x||'').trim().toLowerCase()).filter(Boolean);
f.Client=arr(f.Client||f.client||f.clientRecId||f.clientRecordId).map(x=>(x&&typeof x==='object')?x.id:x).filter(Boolean);
if(!f.Client.length){ throw new Error('Enrich Contacts was called without a Client. Pass the Hub Clients record id as Client. Nothing was pulled.'); }
return [{ json: { id: '', fields: f, _event: true } }];

// Launch Params: the launch row (or the caller's passthrough item, same keys) is the whole
// contract, and since 2026-09-08 it is four fields: Client (resolves the base), Table (by name,
// required, no default, and it must be "Companies": this machine sources people for companies and
// refuses any other table), View (a Companies view, by name, required, no default; the insert
// doors call with "Not Sourced"), Tag (carried for the log only: People stores no Tag, it is a
// lookup through the Companies link). Nothing else is read. Every provider is asked for every
// company; the cap and the seniority floor are rules in code (Plan Batch); a provider with no
// credential on its node is a logged skip. Any missing piece stops the run here, before a call.
//
// REFUSALS (2026-09-03). A launch row that was not properly filled is an EXPECTED outcome, not a
// crash, and it must be visible on the row the Operator launched. So every guard below RETURNS a
// refusal item (`refused` carries the named reason) instead of throwing. `Launch OK?` routes that
// item to Build Refusal, which closes the launch row as Failed with the reason and the execution
// link, and the run ends there: no table read, no call, nothing written.
let rec=null, trigger='form';
try{ rec=$('Fetch Launch Record').first().json; }catch(e){}
if(!rec||!rec.fields){ rec=$('Event Row').first().json; trigger='event'; }
const f=rec.fields||{};
// Resolve Base is allowed to answer with an error item (a launch row with no Client link is asked
// for record "recMISSING"), so read it defensively.
const cf=(($('Resolve Base').first().json||{}).fields)||{};
const base=((cf['Clayroots Base ID']||'')+'').trim();
const arr=(v)=>Array.isArray(v)?v:(v==null||v===''?[]:[v]);
const where='Launch record '+(rec.id||'(event)');
const clientRecId=(arr(f['Client']).map(x=>(x&&typeof x==='object')?x.id:x)[0])||'';
const table=((f['Table']||'')+'').trim();
const view=((f['View']||'')+'').trim();
const tag=((f['Tag']||'')+'').trim();
const domains=arr(f['Domains']).map(x=>String(x||'').trim().toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').replace(/\/.*$/,'')).filter(Boolean);
const startedAt=new Date().toISOString();
const refuse=(reason)=>[{ json:{ refused: reason, trigger: trigger, _launchRecordId: rec.id||'', clientRecId: clientRecId, base: base, table: table, view: view, tag: tag, startedAt: startedAt } }];
if(!clientRecId){ return refuse(where+' has no Client link. Nothing was pulled.'); }
if(!/^app[A-Za-z0-9]{14}$/.test(base)){ return refuse('Client on '+where.toLowerCase()+' has no valid Clayroots Base ID. Nothing was pulled.'); }
if(!table){ return refuse(where+' has no Table. This machine takes Table "Companies" by name, no default. Nothing was pulled.'); }
if(table.toLowerCase()!=='companies'){ return refuse(where+' names Table "'+table+'". This machine sources people for companies and takes only Table "Companies". Nothing was pulled.'); }
if(!view){ return refuse(where+' has no View. A Companies view is required by name, no default (the insert doors pass "Not Sourced"). Nothing was pulled.'); }
return [{ json: { refused: '', base: base, clientRecId: clientRecId, table: 'Companies', view: view, tag: tag, domains: domains, trigger: trigger, _launchRecordId: rec.id||'', startedAt: startedAt } }];

// Find Tables: the client base must already carry tables named exactly "Companies" and
// "People" in the register's shape. Nothing here ever creates a table or a field; the
// scaffold is Onboard Client's job. DNC is optional and found by name. Since 2026-09-08 the
// People field types travel too: Contact Source is written as a list when the base carries it as
// a multi-select, and as the first source only while it is still a single select.
const p=$('Launch Params').first().json;
const r=$input.first().json||{};
const body=(r.body!==undefined)?r.body:r;
const tables=(body&&Array.isArray(body.tables))?body.tables:null;
if(!tables){ throw new Error('Could not read the table list for base '+p.base+': '+JSON.stringify(body).slice(0,200)+'. Nothing was pulled.'); }
const byName=(n)=>tables.find(x=>String(x.name||'').trim().toLowerCase()===n);
const companies=byName('companies');
if(!companies){ throw new Error('Base '+p.base+' has no Companies table. Scaffold the client base to the ClayRoots Standard first. Nothing was pulled.'); }
const people=byName('people');
if(!people){ throw new Error('Base '+p.base+' has no People table. Scaffold the client base to the ClayRoots Standard first. Nothing was pulled.'); }
const cNames=new Set((companies.fields||[]).map(x=>x.name));
for(const need of ['Domain','Company','Employees','Tag','Contacts Pulled At']){ if(!cNames.has(need)){ throw new Error('Companies table '+companies.id+' is missing the core field "'+need+'". Bring it to the register first. Nothing was pulled.'); } }
const pNames=new Set((people.fields||[]).map(x=>x.name));
for(const need of ['Name','Contact Key','Domain','LinkedIn URL','Companies','Contact Source']){ if(!pNames.has(need)){ throw new Error('People table '+people.id+' is missing the core field "'+need+'". Bring it to the register first. Nothing was pulled.'); } }
const pTypes={}; for(const x of (people.fields||[])) pTypes[x.name]=x.type;
const dnc=byName('dnc');
return [{ json: Object.assign({}, p, {
  companiesTableId: companies.id, companiesTableName: companies.name, companiesFields: Array.from(cNames),
  peopleTableId: people.id, peopleTableName: people.name, peopleFields: Array.from(pNames), peopleFieldTypes: pTypes,
  contactSourceMulti: pTypes['Contact Source']==='multipleSelects',
  dncTableId: dnc?dnc.id:'', dncTableName: dnc?dnc.name:''
}) }];

// Pick Companies: the Companies view rows become the run's company list. Rows without a Domain
// are counted and dropped; duplicate domains collapse to one. No cap (ruled 2026-09-08: the view
// is the scope, every company in it is asked). One item out, always, so the empty-pick gate
// reaches the close. The company's Domain is what the batch builds every Contact Key from;
// People stores no Domain, Company or Tag of its own (lookups through the Companies link).
const p=$('Launch Params').first().json;
const norm=(d)=>String(d||'').trim().toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').replace(/\/.*$/,'');
const seen=new Set(); const companies=[];
// An event caller's Domains scope: only view rows whose Domain is in it are picked, the rest are
// counted as outOfScope. Empty scope = the whole view (every launch row).
const scope=new Set((p.domains||[]).map(norm).filter(Boolean));
const stats={ viewRows:0, noDomain:0, duplicate:0, picked:0, outOfScope:0, scoped:scope.size };
for(const it of $input.all()){
  const j=it.json||{}; if(!j.id) continue; stats.viewRows++;
  const f=j.fields||{};
  const d=norm(f.Domain); if(!d){ stats.noDomain++; continue; }
  if(scope.size&&!scope.has(d)){ stats.outOfScope++; continue; }
  if(seen.has(d)){ stats.duplicate++; continue; }
  seen.add(d);
  companies.push({ recordId:j.id, domain:d, company:String(f.Company||'').trim(), employees:String(f.Employees==null?'':f.Employees).trim() });
}
stats.picked=companies.length;
return [{ json: { picked: companies.length, domains: companies.map(c=>c.domain), companies: companies, _stats: stats } }];

// People Filters: tier zero reads what the base already holds at these domains, ids only
// (Contact Key, LinkedIn URL, Domain). Domain on People is a lookup through the Companies link
// (People stores none of its own, ruled 2026-09-02); filterByFormula {Domain}='x' matches the
// lookup's text, so these reads keep working unchanged. One OR formula per 100 domains keeps
// every request under Airtable's URL limit; Read People runs once per item and returns all pages.
const d=$input.first().json.domains||[];
const esc=(s)=>String(s).replace(/\\/g,'\\\\').replace(/'/g,"\\'");
const out=[];
for(let i=0;i<d.length;i+=100){
  const chunk=d.slice(i,i+100);
  out.push({ json: { formula: chunk.length===1?("{Domain}='"+esc(chunk[0])+"'"):('OR('+chunk.map(x=>"{Domain}='"+esc(x)+"'").join(',')+')') } });
}
if(!out.length) out.push({ json: { formula: "{Domain}=''" } });
return out;

// Make Batches: held people per company (tier zero: record id, Contact Key, LinkedIn URL, Email,
// Contact Source, Title, Phone, Seniority, Department, so the batch can FILL blanks on a held row
// instead of skipping it) plus 100 companies per batch item. The batch item carries everything
// the batch needs and the key of the Hub row it will write: parentExecId (this execution) and
// batchNum, dealt once here, 1..N, so "<parentExecId>-<batchNum>" is unique by construction.
// Domain comes back from People as a lookup (an array of one), read array-safe.
const p=$('Launch Params').first().json;
const cfg=$('Find Tables').first().json;
const pick=$('Pick Companies').first().json;
const held={};
let heldRows=0;
const one=(v)=>String(Array.isArray(v)?(v[0]||''):(v==null?'':v)).trim();
const many=(v)=>Array.isArray(v)?v.map(x=>(x&&typeof x==='object')?String(x.name||''):String(x)).filter(Boolean):(v?[String((v&&typeof v==='object')?(v.name||''):v)].filter(Boolean):[]);
try{
  for(const it of $('Read People').all()){
    const j=it.json||{}; if(!j.id) continue;
    const f=j.fields||{};
    const d=one(f.Domain).toLowerCase(); if(!d) continue;
    heldRows++;
    (held[d]=held[d]||[]).push({ id:j.id, key:one(f['Contact Key']).toLowerCase(), linkedin:one(f['LinkedIn URL']), email:one(f.Email), sources:many(f['Contact Source']), title:one(f.Title), phone:one(f.Phone), seniority:one(f.Seniority), department:one(f.Department), sourceId:one(f['Source ID']) });
  }
}catch(e){}
const companies=(pick.companies||[]).map(c=>Object.assign({}, c, { heldRows: held[c.domain]||[] }));
const BATCH=100;
const out=[];
for(let i=0;i<companies.length;i+=BATCH){
  out.push({ json: {
    parentExecId: String($execution.id),
    batchNum: out.length+1, batchCount: Math.ceil(companies.length/BATCH),
    base: p.base, clientRecId: p.clientRecId,
    peopleTableId: cfg.peopleTableId, peopleTableName: cfg.peopleTableName, companiesTableId: cfg.companiesTableId, dncTableId: cfg.dncTableId,
    peopleFields: cfg.peopleFields, contactSourceMulti: cfg.contactSourceMulti===true,
    companies: companies.slice(i,i+BATCH)
  } });
}
if(!out.length) throw new Error('Make Batches received no companies; the empty-pick gate should have caught this.');
out[0].json._stats={ heldRows: heldRows, heldCompanies: companies.filter(c=>c.heldRows.length>0).length, companiesIn: companies.length, batches: out.length };
return out;

// Pass Result: one batch closed (Run Batch, awaited). The sub's last node answers with its
// counters (Batch Response); its own Hub row is already written when it answers. A crash arrives
// as an error item: the parent continues past a dead batch and logs it, it never retries one.
// stop = a batch where every provider that was asked failed: no further batches, straight to the
// close (a provider that was skipped for want of a credential is not a failure).
let batchNum=0; try{ batchNum=Number($('Loop Batches').first().json.batchNum)||0; }catch(e){}
const j=$input.first().json||{};
const out={ batchNum:batchNum, key:String(batchNum), status:'closed', written:0, allFailed:false, stop:false, reason:'' };
if(j.error!==undefined&&j.error!==null&&j.error!==''){
  out.status='crashed';
  out.reason=String((typeof j.error==='object'?(j.error.message||j.error.description||JSON.stringify(j.error)):j.error)||'crashed').slice(0,200);
  return [{ json: out }];
}
if(Number(j.batchNum)>0){ out.batchNum=Number(j.batchNum); out.key=String(out.batchNum); }
out.written=Number(j.written)||0;
out.allFailed=!!j.allFailed;
if(out.allFailed){
  out.status='allFailed';
  out.reason=String((Array.isArray(j.failReasons)&&j.failReasons[0])||'every provider that was asked failed').slice(0,200);
  out.stop=true;
}
return [{ json: out }];

// Find Waterfall View: after every lane group closes, read the base meta again. The email door is
// fired only when the People table carries a view named exactly "Not Waterfalled" (the register's
// view: relevance = 1 and Status empty); otherwise the hand-over is a skip in the log. Nothing else
// (ruled 2026-09-02). No Fire Waterfall field exists on the launch row.
const cfg=$('Find Tables').first().json;
const r=$input.first().json||{};
const body=(r.body!==undefined)?r.body:r;
const tables=(body&&Array.isArray(body.tables))?body.tables:[];
const t=tables.find(x=>x.id===cfg.peopleTableId)||null;
const VIEW='Not Waterfalled';
const v=t?((t.views||[]).find(x=>String(x.name||'').trim()===VIEW)):null;
return [{ json: { hasView: !!v, viewName: VIEW, viewId: v?v.id:'', metaOk: tables.length>0 } }];

// Handoff Tick: the live Running row, written after every batch. The email hand-off is not made
// here: it fires ONCE per run, after the last batch closed (ruled 2026-09-03 after eight
// per-batch calls spawned forty executions and the droplet ran out of memory), against the People
// view "Not Waterfalled". The run so far is read from every Pass Result run (run by run, until a
// run index does not exist). The item out is the row, nothing else, so Stamp Progress can
// auto-map it.
const p=$('Launch Params').first().json;
const cfg=$('Find Tables').first().json;
let batchCount=0, total=0; try{ const s=$('Make Batches').first().json._stats||{}; total=Number(s.companiesIn)||0; batchCount=Number(s.batches)||0; }catch(e){}
const runs=(name)=>{ const out=[]; for(let i=0;i<10000;i++){ let it=null; try{ it=$(name).all(0,i); }catch(e){ break; } if(!it||!it.length) break; out.push(it); } return out; };
const batches=runs('Pass Result').map(r=>r[0].json||{});
const closed=batches.filter(x=>x.status==='closed').length;
const written=batches.reduce((a,x)=>a+(Number(x.written)||0),0);
const inp=$input.first().json||{};
const out={
  'Execution ID': String($execution.id),
  'Automation': 'Enrich Contacts',
  'Trigger': p.trigger||'form',
  'Status': 'Running',
  'Run at': p.startedAt,
  'Target': (cfg.peopleTableName||'People')+' ('+(cfg.peopleTableId||'')+')',
  'Records In': total,
  'Records Out': written,
  'Description': '**Running: '+closed+' of '+batchCount+' batches closed ('+batches.length+' launched, one at a time), '+written+' people rows written so far; batch '+(Number(inp.batchNum)||0)+' '+(inp.status||'closed')+(inp.reason?(' ('+inp.reason+')'):'')+'. The email hand-off fires once, after the last batch.**',
  'Execution Link': 'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id
};
if(p.clientRecId) out['Client']=[p.clientRecId];
return [{ json: out }];

// Build Log: the one launch-row log, written once after the last batch closed and the single email
// hand-off was made or skipped. The counters come from the pass rows: Enrich Contacts Batch writes
// one Hub row per batch keyed "<this execution>-<n>" with its counters JSON in Tally; Read Batch
// Rows pulled them by that prefix and they are summed here (no read-add-write Tally loop). Per
// provider: called, returned, kept, credits, errors, and how many batches it was skipped in and
// why. Status computed from failed[], skips separated from errors, Client attached.
const p=$('Launch Params').first().json;
let cfg={}; try{ cfg=$('Find Tables').first().json||{}; }catch(e){}
let pick={ viewRows:0, noDomain:0, duplicate:0, picked:0, outOfScope:0, scoped:0 };
try{ const j=$('Pick Companies').first().json||{}; if(j._stats) pick=j._stats; }catch(e){}
let mk={ heldRows:0, heldCompanies:0, companiesIn:0, batches:0 };
try{ const j=$('Make Batches').first().json||{}; if(j._stats) mk=j._stats; }catch(e){}
const num=(v)=>Number(v)||0;
const runs=(name)=>{ const out=[]; for(let i=0;i<10000;i++){ let it=null; try{ it=$(name).all(0,i); }catch(e){ break; } if(!it||!it.length) break; out.push(it); } return out; };
const PRIORITY=['Blitz','GetLeads','QuickEnrich','Supersoniq'];
const prov={}; for(const x of PRIORITY) prov[x]={ called:0, returned:0, kept:0, credits:0, errors:0, firstError:'', skipped:0, skipReasons:{}, failedBatches:0, okBatches:0 };
const t={ batches:0, companies:0, returned:0, built:0, updated:0, heldUnchanged:0, dupes:0, noKey:0, fenced:0, emailsAppended:0, dnc:0, written:0, updatedWritten:0, writeErrors:0, stamped:0, stampErrors:0, covered:0, zero:0, zeroDomains:[], failReasons:[], singleSelectSource:false };
const prefix=String($execution.id)+'-';
const rows={};
try{
  for(const it of $('Read Batch Rows').all()){
    const r=it.json||{}; if(!r.id||!r.fields) continue;
    const f=r.fields; const id=String(f['Execution ID']||'');
    if(id.indexOf(prefix)!==0) continue;
    const n=Number(id.slice(prefix.length))||0;
    let c=null; try{ c=JSON.parse(f.Tally||''); }catch(e){}
    if(!c||typeof c!=='object') c=null;
    rows[n]={ status:String(f.Status||''), errors:num(f.Errors), counters:c };
    if(!c) continue;
    t.batches+=1; t.companies+=num(c.companiesIn);
    for(const x of PRIORITY){ const s=(c.providers||{})[x]||{}; const d=prov[x]; if(s.status==='skipped'){ d.skipped++; const k=String(s.reason||'skipped'); d.skipReasons[k]=(d.skipReasons[k]||0)+1; continue; } if(s.status==='error'){ d.failedBatches++; d.errors+=Math.max(1,num(s.errors)); if(!d.firstError) d.firstError=String(s.reason||s.firstError||'').slice(0,300); continue; } d.okBatches++; d.called+=num(s.called); d.returned+=num(s.returned); d.kept+=num(s.kept); d.credits+=num(s.credits); d.errors+=num(s.errors); if(!d.firstError&&s.firstError) d.firstError=String(s.firstError).slice(0,300); }
    for(const k of ['returned','built','updated','heldUnchanged','dupes','noKey','fenced','emailsAppended','dnc','written','updatedWritten','writeErrors','stamped','stampErrors','covered','zero']) t[k]+=num(c[k]);
    if(c.singleSelectSource) t.singleSelectSource=true;
    t.zeroDomains=t.zeroDomains.concat(Array.isArray(c.zeroDomains)?c.zeroDomains:[]).slice(0,50);
    for(const x of (Array.isArray(c.failReasons)?c.failReasons:[])){ if(t.failReasons.length<10) t.failReasons.push(String(x).slice(0,200)); }
  }
}catch(e){}
const rowsRead=Object.keys(rows).length;
const batches=runs('Pass Result').map(r=>r[0].json||{});
const launched=batches.length;
const closed=batches.filter(x=>x.status==='closed').length;
const stopped=batches.find(x=>x.allFailed)||null;
const notLaunched=Math.max(0, num(mk.batches)-launched);
const isFired=(j)=>{ if(!j) return false; if(j.error&&j.statusCode===undefined) return /timeout|timed out|ETIMEDOUT|ESOCKETTIMEDOUT/i.test(String((j.error&&j.error.message)||'')); const s=num(j.statusCode); return s>=200&&s<300; };
const fires=runs('Fire Waterfall').map(r=>r[0].json||{});
const fired=fires.filter(isFired).length;
const fireFailed=fires.length-fired;
const views=runs('Find Waterfall View').map(r=>r[0].json||{});
const viewSkips=views.filter(v=>v.hasView===false&&v.metaOk).length;
const metaFails=views.filter(v=>!v.metaOk).length;
const failed=[]; const skips=[];
for(const x of PRIORITY){ const s=prov[x]; for(let i=0;i<num(s.errors);i++) failed.push({ tier:x, reason:s.firstError||'call failed' }); for(const [k,v] of Object.entries(s.skipReasons)) skips.push(x+' skipped in '+v+' batch'+(v===1?'':'es')+' ('+k+')'); }
for(let i=0;i<num(t.writeErrors);i++) failed.push({ tier:'People writer', reason:'row not in the answer (see the pass rows for the HTTP reason)' });
for(let i=0;i<num(t.stampErrors);i++) failed.push({ tier:'Contacts Pulled At stamp', reason:'row not in the answer' });
for(const x of batches){
  const has=!!rows[x.batchNum];
  if(x.status==='closed'){ if(!has) failed.push({ tier:'Batch '+x.batchNum, reason:'closed but no Hub row was read back under '+prefix+x.batchNum }); continue; }
  if(x.status==='allFailed') failed.push({ tier:'Batch '+x.batchNum, reason:'every provider that was asked failed ('+x.reason+'); no further batches were launched' });
  else if(x.status==='crashed') failed.push({ tier:'Batch '+x.batchNum, reason:'crashed ('+x.reason+'); no counters from it'+(has?', though its row landed and is counted':'') });
  else failed.push({ tier:'Batch '+x.batchNum, reason:x.reason||x.status });
}
for(let i=0;i<metaFails;i++) failed.push({ tier:'Waterfall hand-over', reason:'the base meta could not be read, the view check did not run' });
for(const j of fires){ if(!isFired(j)) failed.push({ tier:'Waterfall hand-over', reason:(j.error&&j.statusCode===undefined)?('door call errored: '+String((j.error&&j.error.message)||'').slice(0,100)):('door HTTP '+j.statusCode) }); }
let dur=0; try{ dur=Math.max(0,Math.round(($now.toMillis()-new Date(p.startedAt).getTime())/1000)); }catch(e){}
const companiesIn=num(pick.picked);
const covered=num(t.covered);
const pct=companiesIn?Math.round(100*covered/companiesIn):0;
const line=(x)=>{ const s=prov[x]; if(!s.okBatches&&!s.failedBatches&&s.skipped) return '- **'+x+':** skipped in every batch ('+Object.keys(s.skipReasons).join('; ')+')'; return '- **'+x+':** called '+num(s.called)+', returned '+num(s.returned)+', kept '+num(s.kept)+(num(s.credits)?', credits '+(Math.round(num(s.credits)*100)/100):'')+(num(s.errors)?', errors '+num(s.errors):'')+(s.skipped?', skipped in '+s.skipped+' batch'+(s.skipped===1?'':'es'):''); };
const zd=Array.isArray(t.zeroDomains)?t.zeroDomains:[];
const lines=[
  '**'+companiesIn+' companies in, '+num(t.built)+' people new, '+num(t.updated)+' held people filled, '+num(t.written)+' rows written into '+(cfg.peopleTableName||'People')+', '+covered+' of '+companiesIn+' covered ('+pct+'%)**',
  '',
  '**Scope:** one client, Companies view "'+p.view+'"'+(p.tag?', Tag "'+p.tag+'"':'')+(pick.scoped?', scoped to the caller\'s '+num(pick.scoped)+' domain(s)':''),
  '**Rule:** every provider asked for every company; cap per provider and seniority floor by the Employees value on our row (up to 50 or unknown: 20 wide; 51 to 500: 30 non-junior; 501 and up: 50 manager and up); merge on Contact Key and LinkedIn slug, first writer wins by priority Blitz, GetLeads, QuickEnrich, Supersoniq; emails appended; held rows filled, never overwritten',
  '',
  '**Funnel**',
  '- **Companies in:** '+companiesIn+' ('+num(pick.viewRows)+' view rows'+(pick.scoped?', '+num(pick.outOfScope)+' outside the scope skipped':'')+', '+num(mk.batches)+' batches of 100)',
  '- **Already held (tier zero):** '+num(mk.heldRows)+' people at '+num(mk.heldCompanies)+' companies'
];
for(const x of PRIORITY) lines.push(line(x));
lines.push('- **Merge:** '+num(t.returned)+' returned; '+num(t.built)+' new rows; '+num(t.updated)+' held rows filled ('+num(t.emailsAppended)+' emails appended); '+num(t.heldUnchanged)+' held unchanged; '+num(t.dupes)+' merged as the same person across providers; '+num(t.noKey)+' without a usable first name; '+num(t.fenced)+' LinkedIn URLs rejected by the name fence; '+num(t.dnc)+' on the DNC table');
if(t.singleSelectSource) lines.push('- **Contact Source is a single select on this base:** only the first source per person was recorded; retype it to a multi-select to record every provider');
lines.push('- **Written (rows in the writer\'s answers):** '+num(t.written)+' ('+num(t.updatedWritten)+' updates of held rows)');
lines.push('- **Coverage:** '+covered+' of '+companiesIn+' companies with at least one person ('+pct+'%)');
lines.push('- **Zero-contact companies:** '+num(t.zero)+(zd.length?' ('+zd.slice(0,20).join(', ')+(zd.length>20?', ...':'')+')':''));
lines.push('- **Contacts Pulled At stamped:** '+num(t.stamped));
lines.push('');
if(companiesIn){
  const bits=[launched+' batch'+(launched===1?'':'es')+' launched one at a time, '+closed+' closed', rowsRead+' pass row'+(rowsRead===1?'':'s')+' read back under "'+prefix+'*" (each pass writes its own Hub row, summed here)'];
  if(stopped) bits.push('stopped after batch '+stopped.batchNum+', every provider that was asked failed in it'+(notLaunched?', '+notLaunched+' not launched':''));
  lines.push('**Passes:** '+bits.join('; '));
}
if(!companiesIn) lines.push('**Waterfall:** not fired, nothing was pulled');
else if(fires.length||viewSkips){
  const bits=[];
  if(fired) bits.push('the hand-off fired once for the whole run'+(fired===1?'':' ('+fired+' calls, which should never happen)')+', to the email door (People view "Not Waterfalled"; the door is not awaited and the email waterfall writes its own rows)');
  if(fireFailed) bits.push('the hand-off failed'+(fireFailed===1?'':' ('+fireFailed+' calls)'));
  if(viewSkips) bits.push('the hand-off was skipped, People had no view "Not Waterfalled"');
  lines.push('**Waterfall:** '+bits.join('; '));
  if(viewSkips) skips.push('the waterfall hand-over was skipped, People has no view "Not Waterfalled"');
}
else lines.push('**Waterfall:** the one hand-off did not run (the base meta could not be read, so the view check gave no verdict)');
if(pick.noDomain) skips.push(num(pick.noDomain)+' view rows without a domain');
if(pick.duplicate) skips.push(num(pick.duplicate)+' duplicate domains in the view');
if(!companiesIn) skips.push('view "'+p.view+'" had no rows to work');
if(notLaunched&&stopped) skips.push(notLaunched+' batches not launched after batch '+stopped.batchNum+' failed every provider');
if(skips.length) lines.push('', '**Skipped ('+skips.join('; ')+')**');
if(failed.length){
  const byReason={}; for(const f of failed){ const k=f.tier+': '+f.reason; byReason[k]=(byReason[k]||0)+1; }
  lines.push('', '**Failures ('+failed.length+')**');
  for(const [r,c] of Object.entries(byReason).slice(0,12)) lines.push('- '+c+' x '+r);
  for(const r of t.failReasons.slice(0,5)) lines.push('- '+r);
}
const tally=Object.assign({}, t, { providers: prov, executionId: String($execution.id), passes: { launched: launched, closed: closed, rows: rowsRead, notLaunched: notLaunched }, handoffs: { fired: fired, failed: fireFailed, skipped: viewSkips } });
const log={
  'Automation':'Enrich Contacts',
  'Status': failed.length?'Succeeded with errors':'Succeeded',
  'Trigger': p.trigger||'form',
  'Errors': failed.length,
  'Run at': $now.toISO(),
  'Target': (cfg.peopleTableName||'People')+' ('+(cfg.peopleTableId||'')+')',
  'View': p.view,
  'Records In': companiesIn,
  'Records Out': num(t.written),
  'Duration s': dur,
  'Description': lines.join('\n'),
  'Tally': JSON.stringify(tally),
  'Execution Link':'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
  'Execution ID': String($execution.id),
  'Client': [p.clientRecId]
};
return [{ json: log }];

// Build Refusal: the row a badly filled launch writes. A refusal is an expected outcome, not a
// crash, so it is logged as one: Launch Params names the reason instead of throwing, Launch OK?
// routes here, and this closes the launch row (already stamped Running with this Execution ID)
// as Failed with the reason and the link. Nothing ran: the guards sit ahead of every call.
const p=$('Launch Params').first().json||{};
const reason=String(p.refused||'the launch row was refused and no reason was recorded');
const show=(v)=>(v===''||v===null||v===undefined||v===0)?'(empty)':String(v);
const lines=[
  '**Refused before anything ran: '+reason+'**',
  '',
  '**Scope:** '+(p.clientRecId?('one client ('+p.clientRecId+')'):'no client resolved')+', launch '+(p._launchRecordId||'(event call, no launch row)'),
  '',
  '**The launch row as this machine read it**',
  '- **Client:** '+show(p.clientRecId),
  '- **Clayroots Base ID:** '+(p.base||'(empty, or the Clients row could not be read)'),
  '- **Table:** '+show(p.table)+' (only "Companies" is accepted)',
  '- **View:** '+show(p.view),
  '- **Tag:** '+show(p.tag),
  '',
  '**Failures (1)**',
  '- Launch guard: '+reason,
  '',
  'No company view was read, no provider was called and nothing was written to the client base.',
  'Fill the named field on the launch row, clear Execution ID, and the Airtable door will fire it again.'
];
let dur=0; try{ dur=Math.max(0,Math.round(($now.toMillis()-new Date(p.startedAt).getTime())/1000)); }catch(e){}
const log={
  'Automation':'Enrich Contacts',
  'Status':'Failed',
  'Trigger': p.trigger||'form',
  'Errors': 1,
  'Run at': $now.toISO(),
  'Records In': 0,
  'Records Out': 0,
  'Duration s': dur,
  'Description': lines.join('\n'),
  'Execution Link':'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
  'Execution ID': String($execution.id)
};
if(p.view) log['View']=p.view;
if(p.clientRecId) log['Client']=[p.clientRecId];
return [{ json: log }];
